const rows = $json.results || [];

let question = "";
try {
  question = $("Build Sustainability Query").first().json.question || "";
} catch (e) {
  question = "";
}

const sustainabilityItems = rows.map((row) => ({
  item_id: row.item_id || null,
  item_type: row.item_type || null,
  item_name: row.item_name || null,
  properties: row.properties || {},
  relationship: row.relationship || null,
  connected_labels: row.connected_labels || [],
  connected_entity: row.connected_entity || null,
}));

return [
  {
    json: {
      agent: "sustainability_analyst",
      domain: "Sustainability Analyst",
      status: "data_retrieved",
      question,
      evidenceLabel: "sustainabilityItems",
      evidenceData: sustainabilityItems,
      rawResult: $json,
    },
  },
];

const agent = $json.agent || "sustainability_analyst";
const domain = $json.domain || "Sustainability Analyst";
const question = $json.question || "";
const evidenceLabel = $json.evidenceLabel || "sustainabilityItems";
const evidenceData = $json.evidenceData || [];
const rawResult = $json.rawResult || {};

const systemPrompt = `
You are a Sustainability Analyst Agent for a supply chain knowledge graph.

Your job:
- Analyze sustainability, material, carbon, emissions, recycling, and waste-related graph data.
- Identify environmental impact patterns, high-carbon areas, recycling opportunities, and material dependencies.
- Explain the business and ESG impact clearly.
- Give practical sustainability recommendations.
- Do not invent facts.
- If graph data is limited or missing sustainability fields, clearly say that.

Return ONLY valid JSON.
`;

const userPrompt = `
User question:
${question}

Sustainability evidence:
${JSON.stringify(evidenceData, null, 2)}

Raw graph result:
${JSON.stringify(rawResult, null, 2)}

Return JSON with this exact schema:
{
  "answer": "string",
  "keyFindings": ["string"],
  "sustainabilityInsights": [
    {
      "id": "string",
      "type": "string",
      "name": "string",
      "impactArea": "carbon | emissions | recycling | waste | material_dependency | unknown",
      "insight": "string"
    }
  ],
  "environmentalConcerns": [
    {
      "concern": "string",
      "evidence": "string",
      "severity": "low | medium | high | unknown"
    }
  ],
  "recommendations": ["string"],
  "confidence": "low | medium | high"
}
`;

return [
  {
    json: {
      agent,
      domain,
      question,
      evidenceLabel,
      evidenceData,
      llmPayload: {
        model: "google/gemma-4-31B-it",
        messages: [
          {
            role: "system",
            content: systemPrompt,
          },
          {
            role: "user",
            content: userPrompt,
          },
        ],
        temperature: 0.2,
        max_tokens: 2048,
      },
    },
  },
];

let outputStr = "";

if ($json.choices?.[0]?.message?.content) {
  outputStr = $json.choices[0].message.content;
} else if ($json.text) {
  outputStr = $json.text;
} else if ($json.response) {
  outputStr = $json.response;
} else {
  outputStr = JSON.stringify($json);
}

outputStr = outputStr
  .replace(/<think>[\s\S]*?<\/think>/gi, "")
  .replace(/^\s*```json/i, "")
  .replace(/^\s*```/i, "")
  .replace(/```\s*$/i, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(outputStr);
} catch (e) {
  parsed = {
    answer: outputStr || "The sustainability analyst could not generate a summary.",
    keyFindings: [],
    sustainabilityInsights: [],
    environmentalConcerns: [],
    recommendations: [],
    confidence: "low",
  };
}

let context = {};
try {
  context = $("Build LLM Summary Payload").first().json;
} catch (e) {
  context = {};
}

return [
  {
    json: {
      agent: "sustainability_analyst",
      domain: "Sustainability Analyst",
      status: "completed",
      question: context.question || "",
      answer: parsed.answer || "",
      keyFindings: parsed.keyFindings || [],
      sustainabilityInsights: parsed.sustainabilityInsights || [],
      environmentalConcerns: parsed.environmentalConcerns || [],
      recommendations: parsed.recommendations || [],
      confidence: parsed.confidence || "medium",
      evidence: {
        sustainabilityItems: context.evidenceData || [],
      },
      rawLlmOutput: parsed,
    },
  },
];

const selectedAgents = $json.selectedAgents || [];

const shouldRun =
  selectedAgents.includes("sustainability_analyst") ||
  selectedAgents.includes("all");

return [
  {
    json: {
      ...$json,
      shouldRun,
    },
  },
];

return [
  {
    json: {
      agent: "sustainability_analyst",
      domain: "Sustainability Analyst",
      status: "skipped",
      question: $json.question || "",
      answer: "",
      keyFindings: [],
      sustainabilityInsights: [],
      environmentalConcerns: [],
      recommendations: [],
      confidence: "not_applicable",
      evidence: {},
    },
  },
];
